84	// applyStrategyOptions sets strategy_options on settings from CLI flags.
85	func (opts *EnableOptions) applyStrategyOptions(settings *EntireSettings) {
86		if opts.SkipPushSessions {
87			if settings.StrategyOptions == nil {
88				settings.StrategyOptions = make(map[string]interface{})
89			}
90			settings.StrategyOptions["push_sessions"] = false
91		}
92		if opts.CheckpointRemote != "" {
93			provider, repo, err := parseCheckpointRemoteFlag(opts.CheckpointRemote)
94			if err != nil {
95				fmt.Fprintf(os.Stderr, "Warning: invalid --checkpoint-remote format: %v\n", err)
96			} else {
97				if settings.StrategyOptions == nil {
98					settings.StrategyOptions = make(map[string]interface{})
99				}
100				settings.StrategyOptions["checkpoint_remote"] = map[string]any{
101					"provider": provider,
102					"repo":     repo,
103				}
104			}
105		}
106	}
