139	// enableUsesSetupFlow reports whether `entire enable` should delegate to the
140	// setup/configure flow instead of the lightweight re-enable path.
141	// Bare `enable` and `enable --local/--project` remain state-toggle operations;
142	// any other setup-mutating flag should share configure's behavior.
143	func enableUsesSetupFlow(cmd *cobra.Command, agentName string) bool {
144		if agentName != "" || hasStrategyFlags(cmd) || hasCheckpointBackendFlag(cmd) || cmd.Flags().Changed(flagSearchSkill) || cmd.Flags().Changed(flagAgentHelpSkill) {
145			return true
146		}
147		return hasGlobalSettingsFlags(cmd) || cmd.Flags().Changed("yes")
148	}
