154	// updateStrategyOptions applies strategy flags to settings without re-running agent setup.
155	// Loads and writes only the target file to avoid leaking settings between layers.
156	func updateStrategyOptions(ctx context.Context, w io.Writer, opts EnableOptions) error {
157		// Validate before doing any I/O so we don't report "Settings updated" on bad input.
158		if opts.CheckpointRemote != "" {
159			if _, _, err := parseCheckpointRemoteFlag(opts.CheckpointRemote); err != nil {
160				return fmt.Errorf("invalid --checkpoint-remote: %w", err)
161			}
162		}
163	
164		targetFile, configDisplay := settingsTargetFile(ctx, opts.UseLocalSettings, opts.UseProjectSettings)
165	
166		targetFileAbs, err := paths.AbsPath(ctx, targetFile)
167		if err != nil {
168			targetFileAbs = targetFile
169		}
170	
171		s, err := settings.LoadFromFile(targetFileAbs)
172		if err != nil {
173			return fmt.Errorf("failed to load settings: %w", err)
174		}
175	
176		opts.applyStrategyOptions(s)
177	
178		if targetFile == settings.EntireSettingsLocalFile {
179			if err := SaveEntireSettingsLocal(ctx, s); err != nil {
180				return fmt.Errorf("failed to save settings: %w", err)
181			}
182		} else {
183			if err := SaveEntireSettings(ctx, s); err != nil {
184				return fmt.Errorf("failed to save settings: %w", err)
185			}
186		}
187	
188		fmt.Fprintf(w, "✓ Settings updated (%s)\n", configDisplay)
189		return nil
190	}
