192	func updateSummaryGenerationSettings(ctx context.Context, w io.Writer, provider, model string, opts EnableOptions) error {
193		if provider == "" && model == "" {
194			return errors.New("at least one of --summarize-provider or --summarize-model must be set")
195		}
196	
197		if provider != "" {
198			// Make external agents on $PATH resolvable for --summarize-provider.
199			external.DiscoverAndRegisterAlways(ctx)
200		}
201	
202		targetFile, configDisplay := settingsTargetFile(ctx, opts.UseLocalSettings, opts.UseProjectSettings)
203		targetFileAbs, err := paths.AbsPath(ctx, targetFile)
204		if err != nil {
205			targetFileAbs = targetFile
206		}
207	
208		s, err := settings.LoadFromFile(targetFileAbs)
209		if err != nil {
210			return fmt.Errorf("failed to load settings: %w", err)
211		}
212		if s.SummaryGeneration == nil {
213			s.SummaryGeneration = &settings.SummaryGenerationSettings{}
214		}
215	
216		if provider != "" {
217			if err := validateSummaryProvider(provider); err != nil {
218				return err
219			}
220			if ag, getErr := getSummaryAgent(types.AgentName(provider)); getErr == nil && external.IsExternal(ag) {
221				if !s.ExternalAgents {
222					s.ExternalAgents = true
223					fmt.Fprintln(w, externalAgentsAutoEnabledNotice)
224				}
225			}
226		}
227		if model != "" && provider == "" && s.SummaryGeneration.Provider == "" {
228			// The target file alone has no provider, but the merged runtime
229			// settings might (e.g. provider in project, model override in local).
230			// Check the full merged view before rejecting.
231			merged, mergeErr := settings.Load(ctx)
232			if mergeErr != nil || merged.SummaryGeneration == nil || merged.SummaryGeneration.Provider == "" {
233				return errors.New("--summarize-model requires an existing summary provider or --summarize-provider")
234			}
235		}
236	
237		s.SummaryGeneration.SetProvider(provider, model)
238	
239		if targetFile == settings.EntireSettingsLocalFile {
240			if err := SaveEntireSettingsLocal(ctx, s); err != nil {
241				return fmt.Errorf("failed to save settings: %w", err)
242			}
243		} else {
244			if err := SaveEntireSettings(ctx, s); err != nil {
245				return fmt.Errorf("failed to save settings: %w", err)
246			}
247		}
248	
249		fmt.Fprintf(w, "✓ Settings updated (%s)\n", configDisplay)
250		return nil
251	}
