288	// updateGlobalSettings persists telemetry / hook-mode flags and reinstalls the
289	// Entire git hook when --force, --absolute-git-hook-path, or --local-dev is set.
290	func updateGlobalSettings(ctx context.Context, cmd *cobra.Command, w io.Writer, opts EnableOptions) error {
291		targetFile, configDisplay := settingsTargetFile(ctx, opts.UseLocalSettings, opts.UseProjectSettings)
292		targetFileAbs, err := paths.AbsPath(ctx, targetFile)
293		if err != nil {
294			targetFileAbs = targetFile
295		}
296		s, err := settings.LoadFromFile(targetFileAbs)
297		if err != nil {
298			return fmt.Errorf("failed to load settings: %w", err)
299		}
300	
301		if cmd.Flags().Changed(flagTelemetry) {
302			v := opts.Telemetry
303			s.Telemetry = &v
304		}
305		if cmd.Flags().Changed(flagAbsoluteGitHookPath) {
306			s.AbsoluteGitHookPath = opts.AbsoluteGitHookPath
307		}
308		if cmd.Flags().Changed(flagLocalDev) {
309			s.LocalDev = opts.LocalDev
310		}
311	
312		if err := saveSettingsToTarget(ctx, s, targetFile); err != nil {
313			return fmt.Errorf("failed to save settings: %w", err)
314		}
315	
316		if cmd.Flags().Changed(flagForce) || cmd.Flags().Changed(flagAbsoluteGitHookPath) || cmd.Flags().Changed(flagLocalDev) {
317			if _, err := strategy.InstallGitHook(ctx, true, s.LocalDev, s.AbsoluteGitHookPath); err != nil {
318				return fmt.Errorf("failed to reinstall git hook: %w", err)
319			}
320			strategy.CheckAndWarnHookManagers(ctx, w, s.LocalDev, s.AbsoluteGitHookPath)
321			fmt.Fprintln(w, "  ✓ Reinstalled git hook")
322		}
323	
324		fmt.Fprintf(w, "✓ Settings updated (%s)\n", configDisplay)
325		return nil
326	}
