328	// settingsTargetFile determines which settings file to write to based on flags
329	// and which files exist. Unlike determineSettingsTarget, this correctly handles
330	// local-only repos by checking for settings.local.json when settings.json is absent.
331	func settingsTargetFile(ctx context.Context, useLocal, useProject bool) (string, string) {
332		if useLocal {
333			return settings.EntireSettingsLocalFile, configDisplayLocal
334		}
335		if useProject {
336			return settings.EntireSettingsFile, configDisplayProject
337		}
338	
339		// No explicit flag — write to whichever file exists.
340		// Check project file first, then local.
341		projectAbs, err := paths.AbsPath(ctx, settings.EntireSettingsFile)
342		if err == nil {
343			if _, statErr := os.Lstat(projectAbs); statErr == nil {
344				return settings.EntireSettingsFile, configDisplayProject
345			}
346		}
347		localAbs, err := paths.AbsPath(ctx, settings.EntireSettingsLocalFile)
348		if err == nil {
349			if _, statErr := os.Lstat(localAbs); statErr == nil {
350				return settings.EntireSettingsLocalFile, configDisplayLocal
351			}
352		}
353	
354		// Neither exists — default to project
355		return settings.EntireSettingsFile, configDisplayProject
356	}
