358	func saveSettingsToTarget(ctx context.Context, s *EntireSettings, targetFile string) error {
359		switch targetFile {
360		case settings.EntireSettingsLocalFile:
361			return SaveEntireSettingsLocal(ctx, s)
362		case settings.EntireSettingsFile:
363			return SaveEntireSettings(ctx, s)
364		default:
365			return fmt.Errorf("unknown settings target %q", targetFile)
366		}
