369	// parseCheckpointRemoteFlag parses a "provider:owner/repo" string into its components.
370	// Supported providers: "github".
371	func parseCheckpointRemoteFlag(value string) (provider, repo string, err error) {
372		parts := strings.SplitN(value, ":", 2)
373		if len(parts) != 2 || parts[0] == "" || parts[1] == "" {
374			return "", "", fmt.Errorf("expected format provider:owner/repo (e.g., github:org/checkpoints-repo), got %q", value)
375		}
376	
377		provider = parts[0]
378		repo = parts[1]
379	
380		switch provider {
381		case checkpointProviderGitHub:
382			// valid
383		default:
384			return "", "", fmt.Errorf("unsupported provider %q (supported: %s)", provider, checkpointProviderGitHub)
385		}
386	
387		repoParts := strings.SplitN(repo, "/", 2)
388		if len(repoParts) != 2 || repoParts[0] == "" || repoParts[1] == "" {
389			return "", "", fmt.Errorf("repo must be in owner/name format, got %q", repo)
390		}
391	
392		return provider, repo, nil
393	}
