395	// runSetupFlow runs the first-time setup flow (agent selection + hooks + settings).
396	// Shared by root command (no args), `entire configure`, and `entire enable` on fresh repos.
397	func runSetupFlow(ctx context.Context, w io.Writer, opts EnableOptions) error {
398		// Discover external agent plugins so they appear in agent selection.
399		// Use DiscoverAndRegisterAlways to bypass the external_agents setting —
400		// during setup the setting doesn't exist yet.
401		external.DiscoverAndRegisterAlways(ctx)
402	
403		var selectFn func(available []string) ([]string, error)
404		if opts.Yes {
405			selectFn = selectAllAgents
406		}
407	
408		agents, err := detectOrSelectAgent(ctx, w, selectFn)
409		if err != nil {
410			return fmt.Errorf("agent selection failed: %w", err)
411		}
412	
413		return runEnableInteractive(ctx, w, agents, opts)
414	}
