425	// hookAgentOptions builds selector options for every registered agent that
426	// supports hooks and isn't test-only (e.g. the Vogon canary), preselecting
427	// the names in selected.
428	func hookAgentOptions(selected map[types.AgentName]struct{}) []huh.Option[string] {
429		agentNames := agent.List()
430		options := make([]huh.Option[string], 0, len(agentNames))
431		for _, name := range agentNames {
432			ag, err := agent.Get(name)
433			if err != nil {
434				continue
435			}
436			if _, ok := agent.AsHookSupport(ag); !ok {
437				continue
438			}
439			if to, ok := ag.(agent.TestOnly); ok && to.IsTestOnly() {
440				continue
441			}
442			opt := huh.NewOption(string(ag.Type()), string(name))
443			if _, ok := selected[name]; ok {
444				opt = opt.Selected(true)
445			}
446			options = append(options, opt)
447		}
448		return options
449	}
