451	// runManageAgents shows which agents are currently enabled and lets the user
452	// add or remove agents. Deselecting an installed agent removes its hooks.
453	func runManageAgents(ctx context.Context, w io.Writer, opts EnableOptions, selectFn func(available []string) ([]string, error)) error {
454		installedNames := GetAgentsWithHooksInstalled(ctx)
455	
456		// Show currently installed agents
457		if len(installedNames) > 0 {
458			fmt.Fprintf(w, "Enabled agents: %s\n\n", strings.Join(agentDisplayNames(installedNames), ", "))
459		}
460	
461		// Build pre-selection set from installed agents
462		installedSet := make(map[types.AgentName]struct{}, len(installedNames))
463		for _, name := range installedNames {
464			installedSet[name] = struct{}{}
465		}
466	
467		// When no selectFn is provided, check if we can prompt interactively.
468		// A selectFn (e.g. from --yes) bypasses the interactive prompt entirely.
469		if selectFn == nil && !interactive.CanPromptInteractively() {
470			if opts.SearchSkill || opts.AgentHelpSkill {
471				if len(installedNames) > 0 {
472					external.DiscoverAndRegisterAlways(ctx)
473					selectedAgentNames := make([]string, 0, len(installedNames))
474					for _, name := range installedNames {
475						selectedAgentNames = append(selectedAgentNames, string(name))
476					}
477					return applyAgentChanges(ctx, w, selectedAgentNames, installedNames, opts)
478				}
479				if opts.SearchSkill {
480					printSkillNonInteractiveNoAgentsGuidance(w, "search skill", flagSearchSkill)
481				}
482				if opts.AgentHelpSkill {
483					printSkillNonInteractiveNoAgentsGuidance(w, "agent-help skill", flagAgentHelpSkill)
484				}
485				return NewSilentError(errors.New("skill install requires an agent in non-interactive mode"))
486			}
487			fmt.Fprintln(w, "Cannot show agent selection in non-interactive mode.")
488			fmt.Fprintln(w, "Use: entire agent add <name>")
489			return nil
490		}
491	
492		// Discover external agent plugins so they appear in agent selection.
493		// Use DiscoverAndRegisterAlways to bypass the external_agents setting —
494		// during setup the setting doesn't exist yet.
495		external.DiscoverAndRegisterAlways(ctx)
496	
497		options := hookAgentOptions(installedSet)
498		if len(options) == 0 {
499			return errors.New("no agents with hook support available")
500		}
501	
502		// Collect available agent names for the selector
503		availableNames := make([]string, 0, len(options))
504		for _, opt := range options {
505			availableNames = append(availableNames, opt.Value)
506		}
507	
508		var selectedAgentNames []string
509		if selectFn != nil {
510			var err error
511			selectedAgentNames, err = selectFn(availableNames)
512			if err != nil {
513				return fmt.Errorf("agent selection cancelled: %w", err)
514			}
515		} else {
516			form := NewAccessibleForm(
517				huh.NewGroup(
518					huh.NewMultiSelect[string]().
519						Title("Manage agents").
520						Description("Use space to select/deselect, enter to confirm.").
521						Options(options...).
522						Value(&selectedAgentNames),
523				),
524			)
525			if err := form.Run(); err != nil {
526				return fmt.Errorf("agent selection cancelled: %w", err)
527			}
528		}
529	
530		// Nothing selected and nothing installed — no-op.
531		if len(selectedAgentNames) == 0 && len(installedNames) == 0 {
532			targetFile, _ := settingsTargetFile(ctx, opts.UseLocalSettings, opts.UseProjectSettings)
533			changed, err := maybePromptVercelDeploymentDisable(ctx, w, targetFile, nil)
534			if err != nil {
535				return err
536			}
537			if !changed {
538				fmt.Fprintln(w, "No changes made.")
539			}
540			return nil
541		}
542	
543		err := applyAgentChanges(ctx, w, selectedAgentNames, installedNames, opts)
544		if err == nil && len(selectedAgentNames) == 0 {
545			fmt.Fprintln(w, "To add agents again, run: entire agent add <name>")
546		}
547		return err
548	}
