550	// applyAgentChanges computes added/removed agent sets from the selection and
551	// installs or uninstalls hooks accordingly.
552	func applyAgentChanges(ctx context.Context, w io.Writer, selectedAgentNames []string, installedNames []types.AgentName, opts EnableOptions) error {
553		installedSet := make(map[types.AgentName]struct{}, len(installedNames))
554		for _, name := range installedNames {
555			installedSet[name] = struct{}{}
556		}
557	
558		selectedSet := make(map[string]struct{}, len(selectedAgentNames))
559		for _, name := range selectedAgentNames {
560			selectedSet[name] = struct{}{}
561		}
562	
563		// Collect errors so partial successes are visible to the user.
564		var errs []error
565	
566		var addedAgents []agent.Agent
567		var reinstalledAgents []agent.Agent
568		for _, name := range selectedAgentNames {
569			ag, err := agent.Get(types.AgentName(name))
570			if err != nil {
571				errs = append(errs, fmt.Errorf("failed to get agent %s: %w", name, err))
572				continue
573			}
574			if _, wasInstalled := installedSet[types.AgentName(name)]; wasInstalled {
575				if opts.ForceHooks {
576					reinstalledAgents = append(reinstalledAgents, ag)
577				}
578				continue
579			}
580			addedAgents = append(addedAgents, ag)
581		}
582	
583		var removedAgents []agent.Agent
584		for _, name := range installedNames {
585			if _, stillSelected := selectedSet[string(name)]; stillSelected {
586				continue
587			}
588			ag, err := agent.Get(name)
589			if err != nil {
590				errs = append(errs, fmt.Errorf("failed to load deselected agent %s: %w", name, err))
591				continue
592			}
593			removedAgents = append(removedAgents, ag)
594		}
595	
596		if len(addedAgents) == 0 && len(reinstalledAgents) == 0 && len(removedAgents) == 0 && len(errs) == 0 && !opts.SearchSkill && !opts.AgentHelpSkill {
597			targetFile, _ := settingsTargetFile(ctx, opts.UseLocalSettings, opts.UseProjectSettings)
598			changed, err := maybePromptVercelDeploymentDisable(ctx, w, targetFile, nil)
599			if err != nil {
600				return err
601			}
602			if !changed {
603				fmt.Fprintln(w, "No changes made.")
604			}
605			return nil
606		}
607		var successfullyAddedAgents []agent.Agent
608		for _, ag := range addedAgents {
609			if _, err := setupAgentHooks(ctx, ag, opts.LocalDev, opts.ForceHooks); err != nil {
610				errs = append(errs, fmt.Errorf("failed to setup %s hooks: %w", ag.Type(), err))
611			} else {
612				successfullyAddedAgents = append(successfullyAddedAgents, ag)
613			}
614		}
615	
616		var successfullyReinstalledAgents []agent.Agent
617		for _, ag := range reinstalledAgents {
618			if _, err := setupAgentHooks(ctx, ag, opts.LocalDev, opts.ForceHooks); err != nil {
619				errs = append(errs, fmt.Errorf("failed to setup %s hooks: %w", ag.Type(), err))
620			} else {
621				successfullyReinstalledAgents = append(successfullyReinstalledAgents, ag)
622			}
623		}
624	
625		var uninstalledAgents []agent.Agent
626		for _, ag := range removedAgents {
627			hookAgent, ok := agent.AsHookSupport(ag)
628			if !ok {
629				logging.Warn(ctx, "installed agent does not support hooks, skipping removal",
630					"agent", string(ag.Name()))
631				continue
632			}
633			if err := hookAgent.UninstallHooks(ctx); err != nil {
634				errs = append(errs, fmt.Errorf("failed to remove %s hooks: %w", ag.Type(), err))
635			} else {
636				uninstalledAgents = append(uninstalledAgents, ag)
637			}
638		}
639	
640		if err := setupOptionalSearchSkillForNames(ctx, w, selectedAgentNames, opts); err != nil {
641			errs = append(errs, err)
642		}
643		if err := setupOptionalAgentHelpSkillForNames(ctx, w, selectedAgentNames, opts); err != nil {
644			errs = append(errs, err)
645		}
646	
647		// Auto-enable external_agents setting if any new agent is external.
648		for _, ag := range append(successfullyAddedAgents, successfullyReinstalledAgents...) {
649			if external.IsExternal(ag) {
650				s, loadErr := LoadEntireSettings(ctx)
651				if loadErr != nil {
652					s = &EntireSettings{}
653				}
654				if !s.ExternalAgents {
655					s.ExternalAgents = true
656					var saveErr error
657					if opts.UseLocalSettings {
658						saveErr = SaveEntireSettingsLocal(ctx, s)
659					} else {
660						saveErr = SaveEntireSettings(ctx, s)
661					}
662					if saveErr != nil {
663						errs = append(errs, fmt.Errorf("failed to save external_agents setting: %w", saveErr))
664					}
665				}
666				break
667			}
668		}
669	
670		// Print summary of what succeeded
671		if len(successfullyAddedAgents) > 0 {
672			names := make([]string, 0, len(successfullyAddedAgents))
673			for _, ag := range successfullyAddedAgents {
674				names = append(names, string(ag.Type()))
675			}
676			fmt.Fprintf(w, "✓ Added agents: %s\n", strings.Join(names, ", "))
677		}
678		if len(successfullyReinstalledAgents) > 0 {
679			names := make([]string, 0, len(successfullyReinstalledAgents))
680			for _, ag := range successfullyReinstalledAgents {
681				names = append(names, string(ag.Type()))
682			}
683			fmt.Fprintf(w, "✓ Reinstalled agents: %s\n", strings.Join(names, ", "))
684		}
685		if len(uninstalledAgents) > 0 {
686			if len(successfullyAddedAgents) == 0 && len(successfullyReinstalledAgents) == 0 && len(addedAgents) == 0 && len(removedAgents) == len(installedNames) {
687				fmt.Fprintln(w, "All agents have been removed.")
688			} else {
689				names := make([]string, 0, len(uninstalledAgents))
690				for _, ag := range uninstalledAgents {
691					names = append(names, string(ag.Type()))
692				}
693				fmt.Fprintf(w, "✓ Removed agents: %s\n", strings.Join(names, ", "))
694			}
695		}
696	
697		vercelSettingsTarget, _ := settingsTargetFile(ctx, opts.UseLocalSettings, opts.UseProjectSettings)
698		if _, err := maybePromptVercelDeploymentDisable(ctx, w, vercelSettingsTarget, nil); err != nil {
699			errs = append(errs, err)
700		}
701	
702		return errors.Join(errs...)
703	}
