797	func newEnableCmd() *cobra.Command {
798		var opts EnableOptions
799		var ignoreUntracked bool
800		var agentName string
801		var bootstrapOpts GitHubBootstrapOptions
802		var insecureHTTPAuth bool
803	
804		cmd := &cobra.Command{
805			Use:   "enable",
806			Short: "Enable Entire in current repository",
807			Long: `Enable Entire with session tracking for your AI agent workflows.
808	
809	If Entire is not yet configured, this runs the full configuration flow.
810	If Entire is already configured but disabled, this re-enables it.
811	
812	If the current directory is not a git repository, Entire can initialize one
813	for you and (optionally) create a matching GitHub repository via the gh CLI.`,
814			RunE: func(cmd *cobra.Command, _ []string) (runErr error) {
815				ctx := cmd.Context()
816				// Best-effort: after a successful enable, tell the backend which repo
817				// was enabled so the web onboarding reflects it (and we can warn when
818				// the GitHub App can't reach it). Registered first so it runs LAST
819				// (defers are LIFO) — after any bootstrap finalize that creates the
820				// GitHub repo and pushes, by which point an origin remote exists.
821				defer func() {
822					if runErr != nil {
823						return
824					}
825					reportRepoEnabled(ctx, insecureHTTPAuth)
826				}()
827	
828				// Validate --checkpoint-backend up front so a bad value fails before we
829				// bootstrap a repo or install any hooks.
830				if hasCheckpointBackendFlag(cmd) {
831					if _, err := resolveCheckpointBackendType(opts.CheckpointBackend); err != nil {
832						cmd.SilenceUsage = true
833						return err
834					}
835				}
836	
837				// Check if we're in a git repository first. If not, offer to
838				// bootstrap one (git init + optional GitHub repo). If the user
839				// declines, fall back to the legacy prerequisite error.
840				//
841				// The bootstrap runs in two phases: phase 1 (git init + identity
842				// + gather GitHub choices) before agent setup, phase 2
843				// (initial commit + gh repo create + push) after agent setup so
844				// the initial commit captures the .entire/, .claude/, hooks, and
845				// settings files that setup writes.
846				var bootstrap *bootstrapState
847				if _, err := paths.WorktreeRoot(ctx); err != nil {
848					bootstrapOpts.Yes = opts.Yes
849					state, bootstrapErr := runGitHubBootstrapInit(ctx, cmd.OutOrStdout(), cmd.ErrOrStderr(), bootstrapOpts)
850					if errors.Is(bootstrapErr, errBootstrapDeclined) {
851						fmt.Fprintln(cmd.ErrOrStderr(), "Not a git repository. Please run 'entire enable' from within a git repository, or pass --init-repo to initialize one here.")
852						return NewSilentError(errors.New("not a git repository"))
853					}
854					if errors.Is(bootstrapErr, errBootstrapInterrupted) {
855						fmt.Fprintln(cmd.ErrOrStderr(), "Bootstrap cancelled. A local git repository has been initialized but setup didn't complete. Run `entire enable` again to continue.")
856						return NewSilentError(errors.New("bootstrap interrupted"))
857					}
858					if bootstrapErr != nil {
859						return bootstrapErr
860					}
861					bootstrap = state
862					// Let the enable flow know that we'll be handling the final
863					// "done" summary from the bootstrap finalize step.
864					opts.SuppressDoneMessage = true
865					// Re-check after bootstrap.
866					if _, err := paths.WorktreeRoot(ctx); err != nil {
867						return fmt.Errorf("bootstrap finished but no git repository detected: %w", err)
868					}
869					// Visual separator between bootstrap init and agent setup.
870					printBootstrapSection(cmd.OutOrStdout(), "Enabling Entire")
871					// On the way out (if setup succeeded), create the initial
872					// commit and push to the GitHub repo. If setup returned an
873					// error, skip the finalize — the user can fix the issue and
874					// re-run; any partial state is just untracked files.
875					defer func() {
876						if runErr != nil || bootstrap == nil {
877							return
878						}
879						if err := runGitHubBootstrapFinalize(ctx, cmd.OutOrStdout(), bootstrap); err != nil {
880							runErr = err
881						}
882					}()
883				}
884	
885				if err := validateSetupFlags(opts.UseLocalSettings, opts.UseProjectSettings); err != nil {
886					return err
887				}
888	
889				// Discover external agent plugins early so --agent can find them.
890				// Use DiscoverAndRegisterAlways so that --agent works on fresh repos
891				// where the external_agents setting hasn't been persisted yet.
892				external.DiscoverAndRegisterAlways(ctx)
893	
894				// Non-interactive mode if --agent flag is provided
895				if cmd.Flags().Changed(agentFlagName) && agentName == "" {
896					printMissingAgentError(cmd.ErrOrStderr())
897					return NewSilentError(errors.New("missing agent name"))
898				}
899	
900				if agentName != "" {
901					ag, err := agent.Get(types.AgentName(agentName))
902					if err != nil {
903						printWrongAgentError(cmd.ErrOrStderr(), agentName)
904						return NewSilentError(errors.New("wrong agent name"))
905					}
906					// --agent is a targeted operation: set up this specific agent without
907					// affecting other agents. Unlike the interactive path, it does not
908					// uninstall hooks for other previously-enabled agents.
909					return setupAgentHooksNonInteractive(ctx, cmd.OutOrStdout(), ag, opts)
910				}
911	
912				// Any setup-mutating flags should behave like `configure` on repos that
913				// are already set up. Bare `enable` remains the lightweight re-enable path.
914				if settings.IsSetUpAny(ctx) {
915					return runEnableOnConfiguredRepo(ctx, cmd, opts)
916				}
917	
918				// Fresh repo — run full setup flow
919				return runSetupFlow(ctx, cmd.OutOrStdout(), opts)
920			},
921		}
