967	// reportRepoEnabled records the `entire enable` against the backend so the web
968	// onboarding can reflect it. It is strictly best-effort and fully silent:
969	// enabling works offline, and every outcome (no origin remote, not logged in,
970	// network error, App-can't-reach-repo) is swallowed — the web onboarding
971	// surfaces the "install the GitHub App" nudge, so the CLI stays quiet.
972	func reportRepoEnabled(ctx context.Context, insecureHTTPAuth bool) {
973		// This runs synchronously on the enable success path, so bound it: a backend
974		// that accepts the connection but never responds must not hang the command
975		// after it has already printed success.
976		ctx, cancel := context.WithTimeout(ctx, 5*time.Second)
977		defer cancel()
978	
979		rawURL, err := gitremote.GetRemoteURL(ctx, "origin")
980		if err != nil || strings.TrimSpace(rawURL) == "" {
981			// Local-only repo with no origin yet — nothing to report.
982			return
983		}
984	
985		info, err := gitremote.ParseURL(rawURL)
986		if err != nil {
987			logging.Debug(ctx, "skipping enable report: unparseable origin remote", "error", err)
988			return
989		}
990		if info.Forge == "" {
991			// Trails are only available for remotes that map to a supported forge.
992			// Persist the negative locally even if auth is unavailable so a stale true
993			// cache from a previous origin does not inject on the prompt path. No API
994			// report is useful for non-forge remotes.
995			if err := saveTrailsEnabledForRemote(ctx, info.Forge, info.Owner, info.Repo, false); err != nil {
996				logging.Debug(ctx, "failed to cache trails enablement", "error", err)
997			}
998			return
999		}
1000	
1001		cleanURL, err := cleanRemoteURLForReport(rawURL)
1002		if err != nil {
1003			logging.Debug(ctx, "skipping enable report: unparseable origin remote", "error", err)
1004			return
1005		}
1006	
1007		client, err := NewAuthenticatedAPIClient(ctx, insecureHTTPAuth)
1008		if err != nil {
1009			// Not logged in / token unavailable — enable already succeeded locally.
1010			logging.Debug(ctx, "skipping enable report", "error", err)
1011			return
1012		}
1013	
1014		if _, err := client.ReportEnable(ctx, cleanURL); err != nil {
1015			// The enable report is best-effort and independent from the trails cache:
1016			// still try the trails probe so a reporting failure doesn't leave the
1017			// prompt-path cache stale or unknown.
1018			logging.Debug(ctx, "enable report failed", "error", err)
1019		}
1020	
1021		enabled, err := client.TrailsEnabled(ctx, info.Forge, info.Owner, info.Repo)
1022		if err != nil {
1023			logging.Debug(ctx, "trails enablement probe failed", "error", err)
1024			return
1025		}
1026		if err := saveTrailsEnabledForRemote(ctx, info.Forge, info.Owner, info.Repo, enabled); err != nil {
1027			logging.Debug(ctx, "failed to cache trails enablement", "error", err)
1028		}
1029	}
1030	
1031	// cleanRemoteURLForReport turns a raw git remote URL into a clean,
1032	// credential-free HTTPS URL safe to send to the backend. The raw remote can
1033	// carry embedded credentials (https://token@host/...) or query params, so we
1034	// never forward it verbatim: parse it and rebuild from host/owner/repo alone.
1035	// Returns an error if the URL can't be parsed (the caller skips reporting).
1036	func cleanRemoteURLForReport(rawURL string) (string, error) {
1037		info, err := gitremote.ParseURL(rawURL)
1038		if err != nil {
1039			return "", fmt.Errorf("parse remote URL: %w", err)
1040		}
1041		// Use CanonicalHost, not Host: an entire://cluster/gh/owner/repo origin (an
1042		// already-mirrored repo) carries the Entire cluster as Host, so reporting
1043		// Host verbatim would point the backend at the cluster instead of github.com.
1044		return fmt.Sprintf("https://%s/%s/%s.git", info.CanonicalHost(), info.Owner, info.Repo), nil
1045	}
