1089		w := cmd.OutOrStdout()
1090		usedSetupFlow := enableUsesSetupFlow(cmd, "")
1091		if usedSetupFlow {
1092			if hasStrategyFlags(cmd) {
1093				if err := updateStrategyOptions(ctx, w, opts); err != nil {
1094					return err
1095				}
1096			}
1097			if hasCheckpointBackendFlag(cmd) {
1098				if err := updateCheckpointBackend(ctx, w, opts); err != nil {
1099					return err
1100				}
