1102			if enableNeedsAgentManagement(cmd) {
1103				var selectFn func(available []string) ([]string, error)
1104				if opts.Yes {
1105					selectFn = selectAllAgents
1106				}
1107				if err := runManageAgents(ctx, w, opts, selectFn); err != nil {
1108					return err
