50	// bootstrapRunner executes external commands. Tests override this to avoid
51	// shelling out to git/gh.
52	type bootstrapRunner interface {
53		// Run executes the command and returns stdout. Stderr is available on
54		// the returned *exec.ExitError for error reporting.
55		Run(ctx context.Context, name string, args ...string) (string, error)
56		// RunInDir is Run with an explicit working directory.
57		RunInDir(ctx context.Context, dir, name string, args ...string) (string, error)
58	}
