74	// printBootstrapSection writes a small section header so the bootstrap
75	// output has visual grouping between phases (git init → agent setup →
76	// commit & push). Kept simple text so it renders correctly in accessible
77	// mode and non-TTY captures.
78	func printBootstrapSection(w io.Writer, title string) {
79		fmt.Fprintf(w, "\n%s\n", title)
80	}
81	
82	// errBootstrapDeclined signals that the user chose not to initialize a
83	// repo. Returned _before_ `git init` runs; callers fall back to the
84	// legacy "Not a git repository" error.
85	var errBootstrapDeclined = errors.New("bootstrap declined")
86	
87	// errBootstrapInterrupted signals that the user aborted a prompt _after_
88	// `git init` has already run. The local repo is in place but setup
89	// didn't complete; callers should surface that clearly instead of
90	// pretending no init happened.
91	var errBootstrapInterrupted = errors.New("bootstrap interrupted after init")
92	
93	// ghRepoNameRe validates GitHub repository names. GitHub allows
94	// alphanumerics, hyphens, underscores, and periods — including as the
95	// first character (e.g. `.github`). We don't enforce a leading-char
96	// restriction here; `validateRepoName` handles the specific names GitHub
97	// reserves (`.`, `..`). Any other edge case is left to GitHub to reject
98	// so we don't over-restrict.
99	var ghRepoNameRe = regexp.MustCompile(`^[A-Za-z0-9._-]+$`)
100	
101	// allowed visibility values.
102	const (
103		visibilityPublic   = "public"
104		visibilityPrivate  = "private"
105		visibilityInternal = "internal"
106	)
