108	// bootstrapState carries pre-setup decisions into the post-setup finalize
109	// step. The caller runs `runGitHubBootstrapInit` before agent setup to do
110	// `git init` + identity + gather GitHub choices, then runs
111	// `runGitHubBootstrapFinalize` afterwards so the initial commit captures
112	// the `.entire/`, `.claude/`, etc. files written during setup.
113	type bootstrapState struct {
114		runner     bootstrapRunner
115		cwd        string
116		useGitHub  bool
117		fullName   string // owner/name, if useGitHub
118		visibility string // public/private/internal, if useGitHub
119		commit     bool   // false means the user opted out of the initial commit
120		message    string // resolved initial commit message (empty when !commit)
121	}
122	
123	// runGitHubBootstrapInit handles the pre-setup half of "enable on a non-git
124	// folder": confirm + `git init`, ensure git identity, and (if we're going
125	// to create a GitHub repo) gather owner/name/visibility up front so all
126	// prompts happen before agent setup runs.
127	//
128	// Returns errBootstrapDeclined if the user declined the init prompt.
129	// Returns nil, nil if the caller is already inside a git repo and no
130	// bootstrap is needed (defensive; the caller typically gates on this).
131	func runGitHubBootstrapInit(ctx context.Context, w, errW io.Writer, opts GitHubBootstrapOptions) (*bootstrapState, error) {
132		return runGitHubBootstrapInitWith(ctx, w, errW, opts, execRunner{})
133	}
134	
135	// runGitHubBootstrapInitWith is the testable variant that accepts a runner.
136	func runGitHubBootstrapInitWith(ctx context.Context, w, errW io.Writer, opts GitHubBootstrapOptions, runner bootstrapRunner) (*bootstrapState, error) {
137		// paths.RepoRoot is unavailable here — we're bootstrapping _before_ a
138		// repo exists. Plain cwd is the correct target for `git init`.
139		cwd, err := os.Getwd() //nolint:forbidigo // no repo yet; git init runs in cwd
140		if err != nil {
141			return nil, fmt.Errorf("get working directory: %w", err)
142		}
143	
144		// Step 1: confirm we should git init here.
145		proceed, err := confirmInitRepo(w, cwd, opts)
146		if err != nil {
147			return nil, err
148		}
149		if !proceed {
150			return nil, errBootstrapDeclined
151		}
152	
153		// Step 2: git init.
154		printBootstrapSection(w, "Setting up git repository")
155		if err := gitInit(ctx, runner, cwd); err != nil {
156			return nil, fmt.Errorf("git init: %w", err)
157		}
158		// Clear cached worktree root so subsequent paths.WorktreeRoot calls pick
159		// up the freshly created repo.
160		paths.ClearWorktreeRootCache()
161		fmt.Fprintln(w, "  ✓ Initialized empty git repository")
162	
163		// Step 3: decide whether to create a GitHub repo. If gh is missing or the
164		// user passed --no-github, we skip that branch but still bootstrap the
165		// local repo.
166		useGitHub := !opts.NoGitHub
167		if useGitHub {
168			if !ghAvailable(ctx, runner) {
169				fmt.Fprintln(errW, "gh CLI not found. Install it from https://cli.github.com/ and run `gh auth login` to add a GitHub remote.")
170				fmt.Fprintln(errW, "Continuing with local initialization only.")
171				useGitHub = false
172			} else if !ghAuthenticated(ctx, runner) {
173				fmt.Fprintln(errW, "gh CLI is not authenticated. Run `gh auth login` to add a GitHub remote.")
174				fmt.Fprintln(errW, "Continuing with local initialization only.")
175				useGitHub = false
176			}
177		}
178	
179		// Step 3b: ask a simple yes/no before diving into owner/name/visibility
180		// prompts. Skip the confirm when any gh-specific flag is set (the flag
181		// implies intent) or when we're non-interactive (keep the documented
182		// happy path: default to yes).
183		if useGitHub && !opts.Yes && !ghFlagsProvided(opts) && interactive.CanPromptInteractively() {
184			confirmed, err := confirmCreateGitHubRepo()
185			if err != nil {
186				return nil, err
187			}
188			if !confirmed {
189				useGitHub = false
190			}
191		}
192	
193		// Step 4: collect GitHub repo details up front so all prompts are
194		// contiguous.
195		var fullName, visibility string
196		if useGitHub {
197			owner, name, vis, err := selectGitHubRepo(ctx, w, errW, runner, cwd, opts)
198			if err != nil {
199				return nil, err
200			}
201			fullName = owner + "/" + name
202			visibility = vis
203		}
204	
205		// Step 5: resolve commit message (+ skip decision) and ensure git
206		// identity. Must run after `git init` so `git config` reads are
207		// scoped correctly. If the user chose to skip the commit we still
208		// need an identity *if* we're going to create the GitHub repo,
209		// because gh may read local config; but we can skip the identity
210		// check when the user is fully opting out of both commit and
211		// remote to keep the flow minimal.
212		message, commit, err := resolveCommitMessage(opts)
213		if err != nil {
214			return nil, err
215		}
216		if commit {
217			if err := ensureGitIdentity(ctx, w, errW, runner, cwd); err != nil {
218				return nil, err
219			}
220		}
221	
222		return &bootstrapState{
223			runner:     runner,
224			cwd:        cwd,
225			useGitHub:  useGitHub,
226			fullName:   fullName,
227			visibility: visibility,
228			commit:     commit,
229			message:    message,
230		}, nil
231	}
