233	// runGitHubBootstrapWith runs the full bootstrap (init + finalize) in one
234	// call, used by tests that don't need to assert phasing. The real caller
235	// runs the two phases around agent setup.
236	func runGitHubBootstrapWith(ctx context.Context, w, errW io.Writer, opts GitHubBootstrapOptions, runner bootstrapRunner) error {
237		state, err := runGitHubBootstrapInitWith(ctx, w, errW, opts, runner)
238		if err != nil {
239			return err
240		}
241		return runGitHubBootstrapFinalize(ctx, w, state)
242	}
243	
244	// runGitHubBootstrapFinalize runs the post-setup half: stage + initial
245	// commit (now including any `.entire/`, agent hook, and settings files
246	// written by the enable flow), then create the GitHub repo and push.
247	// If the user opted out of the initial commit we still create the
248	// GitHub repo (if they opted in) but skip the push — there's nothing to
249	// push — and print next-step instructions.
250	func runGitHubBootstrapFinalize(ctx context.Context, w io.Writer, s *bootstrapState) error {
251		if s == nil {
252			return nil
253		}
254	
255		// Pick a single section title for this phase based on what we'll do.
256		if s.useGitHub || s.commit {
257			switch {
258			case s.useGitHub && s.commit:
259				printBootstrapSection(w, "Publishing to GitHub")
260			case s.useGitHub:
261				printBootstrapSection(w, "Creating GitHub repository")
262			default:
263				printBootstrapSection(w, "Finalizing")
264			}
265		}
266	
267		var committed bool
268		if s.commit {
269			c, err := doInitialCommit(ctx, s.runner, s.cwd, s.message)
270			if err != nil {
271				return fmt.Errorf("initial commit: %w", err)
272			}
273			committed = c
274			if committed {
275				fmt.Fprintln(w, "  ✓ Created initial commit")
276			} else {
277				fmt.Fprintln(w, "  ✓ Nothing to commit — the folder has no files yet")
278			}
279		}
280		if s.useGitHub {
281			if err := ghRepoCreate(ctx, s.runner, s.cwd, s.fullName, s.visibility, committed); err != nil {
282				return fmt.Errorf("gh repo create: %w", err)
283			}
284			fmt.Fprintf(w, "  ✓ Created %s (%s)\n", s.fullName, s.visibility)
285			fmt.Fprintf(w, "    https://github.com/%s\n", s.fullName)
286			if committed {
287				fmt.Fprintln(w, "  ✓ Pushed initial commit to origin")
288			}
289		}
290		if !s.commit {
291			fmt.Fprintln(w)
292			fmt.Fprintln(w, "  Skipped initial commit. When you're ready:")
293			fmt.Fprintln(w, "    git add -A && git commit -m \"Initial commit\"")
294			if s.useGitHub {
295				fmt.Fprintln(w, "    git push -u origin HEAD")
296			}
297		}
298	
299		fmt.Fprintln(w, "\nDone.")
300		return nil
301	}
