310	// confirmCreateGitHubRepo asks the user whether they want to also create
311	// a matching GitHub repository. Interactive-only; callers gate on
312	// interactive.CanPromptInteractively.
313	func confirmCreateGitHubRepo() (bool, error) {
314		confirmed := true
315		form := NewAccessibleForm(
316			huh.NewGroup(
317				huh.NewConfirm().
