365	// selectGitHubRepo gathers owner, repo name, and visibility, respecting
366	// supplied flags and falling back to interactive prompts.
367	func selectGitHubRepo(ctx context.Context, w, errW io.Writer, runner bootstrapRunner, cwd string, opts GitHubBootstrapOptions) (owner, name, visibility string, err error) {
368		currentUser, userErr := ghCurrentUser(ctx, runner)
369		if userErr != nil {
370			return "", "", "", fmt.Errorf("query current gh user: %w", userErr)
371		}
372		orgs, orgErr := ghListOrgs(ctx, runner)
373		if orgErr != nil {
374			// Missing read:org scope is non-fatal — we can still offer the user
375			// account. Warn and continue.
376			fmt.Fprintf(errW, "Warning: could not list organizations (%v). Only your user account is available.\n", orgErr)
377			orgs = nil
378		}
379	
380		owner, err = resolveOwner(w, currentUser, orgs, opts)
381		if err != nil {
382			return "", "", "", err
383		}
384	
385		name, err = resolveRepoName(ctx, w, errW, runner, owner, cwd, opts)
386		if err != nil {
387			return "", "", "", err
388		}
389	
390		visibility, err = resolveVisibility(owner, currentUser, opts)
391		if err != nil {
392			return "", "", "", err
393		}
394	
395		return owner, name, visibility, nil
396	}
