398	func resolveOwner(w io.Writer, currentUser string, orgs []string, opts GitHubBootstrapOptions) (string, error) {
399		owners := append([]string{currentUser}, orgs...)
400		if opts.RepoOwner != "" {
401			for _, candidate := range owners {
402				if candidate == opts.RepoOwner {
403					return opts.RepoOwner, nil
404				}
405			}
406			// Owner not in known list — allow it anyway; gh repo create will
407			// error out later if invalid. This supports orgs the token can't
408			// enumerate (e.g. missing read:org scope).
409			return opts.RepoOwner, nil
410		}
411		if len(owners) == 1 || opts.Yes {
412			fmt.Fprintf(w, "  Using GitHub owner: %s\n", currentUser)
413			return currentUser, nil
414		}
415		if !interactive.CanPromptInteractively() {
416			return currentUser, nil
417		}
418	
419		options := make([]huh.Option[string], 0, len(owners))
420		for _, o := range owners {
421			options = append(options, huh.NewOption(o, o))
422		}
423		selected := currentUser
424		form := NewAccessibleForm(
425			huh.NewGroup(
426				huh.NewSelect[string]().
427					Title("Choose the GitHub owner for the new repository").
428					Options(options...).
429					Value(&selected),
430			),
431		)
432		if err := form.Run(); err != nil {
433			if errors.Is(err, huh.ErrUserAborted) {
434				return "", errBootstrapInterrupted
435			}
436			return "", fmt.Errorf("owner prompt: %w", err)
437		}
438		return selected, nil
439	}
