441	func resolveRepoName(ctx context.Context, w, errW io.Writer, runner bootstrapRunner, owner, cwd string, opts GitHubBootstrapOptions) (string, error) {
442		suggested := slugifyRepoName(filepath.Base(cwd))
443	
444		if opts.RepoName != "" {
445			if err := validateRepoName(opts.RepoName); err != nil {
446				return "", err
447			}
448			exists, checkErr := ghRepoExists(ctx, runner, owner, opts.RepoName)
449			if checkErr != nil {
450				fmt.Fprintf(errW, "Warning: could not check if %s/%s already exists (%v).\n", owner, opts.RepoName, checkErr)
451			} else if exists {
452				return "", fmt.Errorf("repository %s/%s already exists on GitHub", owner, opts.RepoName)
453			}
454			return opts.RepoName, nil
455		}
456	
457		if opts.Yes {
458			// Check availability before blindly using the suggested name.
459			exists, checkErr := ghRepoExists(ctx, runner, owner, suggested)
460			if checkErr != nil {
461				// Check failed — proceed with the suggested name and let gh
462				// error later if the name is actually taken.
463				fmt.Fprintf(errW, "Warning: could not check if %s/%s already exists (%v).\n", owner, suggested, checkErr)
464				return suggested, nil
465			}
466			if !exists {
467				return suggested, nil
468			}
469			// Name taken. If a TTY is available, fall back to the interactive
470			// prompt so the user can pick a different name instead of failing.
471			if interactive.CanPromptInteractively() {
472				fmt.Fprintf(w, "  %s/%s already exists on GitHub.\n", owner, suggested)
473			} else {
474				return "", fmt.Errorf("repository %s/%s already exists on GitHub (use --repo-name to specify a different name)", owner, suggested)
475			}
476		}
477		if !interactive.CanPromptInteractively() {
478			return suggested, nil
479		}
480	
481		name := suggested
482		for {
483			var input string
484			form := NewAccessibleForm(
485				huh.NewGroup(
486					huh.NewInput().
487						Title("Repository name").
488						Description(fmt.Sprintf("Press enter to use %q", name)).
489						Value(&input),
490				),
491			).WithOutput(w)
492			if err := form.Run(); err != nil {
493				if errors.Is(err, huh.ErrUserAborted) {
494					return "", errBootstrapInterrupted
495				}
496				return "", fmt.Errorf("repo name prompt: %w", err)
497			}
498			if strings.TrimSpace(input) != "" {
499				name = strings.TrimSpace(input)
500			}
501			if err := validateRepoName(name); err != nil {
502				fmt.Fprintf(errW, "Invalid name: %v\n", err)
503				continue
504			}
505			exists, checkErr := ghRepoExists(ctx, runner, owner, name)
506			if checkErr != nil {
507				fmt.Fprintf(errW, "Warning: could not check if %s/%s already exists (%v). Proceeding; gh will error out if it is taken.\n", owner, name, checkErr)
508				return name, nil
509			}
510			if exists {
511				fmt.Fprintf(w, "%s/%s already exists on GitHub. Pick a different name.\n", owner, name)
512				continue
513			}
514			return name, nil
515		}
516	}
