518	func resolveVisibility(owner, currentUser string, opts GitHubBootstrapOptions) (string, error) {
519		isOrg := owner != currentUser
520	
521		if opts.RepoVisibility != "" {
522			vis := strings.ToLower(opts.RepoVisibility)
523			switch vis {
524			case visibilityPublic, visibilityPrivate:
525				return vis, nil
526			case visibilityInternal:
527				if !isOrg {
528					return "", errors.New("visibility 'internal' is only available for organization repositories")
529				}
530				return vis, nil
531			default:
532				return "", fmt.Errorf("invalid visibility %q: must be one of public, private, internal", opts.RepoVisibility)
533			}
534		}
535		if opts.Yes || !interactive.CanPromptInteractively() {
536			return visibilityPrivate, nil
537		}
538	
539		options := []huh.Option[string]{
540			huh.NewOption("Private", visibilityPrivate),
541			huh.NewOption("Public", visibilityPublic),
542		}
543		if isOrg {
544			options = append(options, huh.NewOption("Internal", visibilityInternal))
545		}
546		selected := visibilityPrivate
547		form := NewAccessibleForm(
548			huh.NewGroup(
549				huh.NewSelect[string]().
550					Title("Repository visibility").
551					Options(options...).
552					Value(&selected),
553			),
554		)
555		if err := form.Run(); err != nil {
556			if errors.Is(err, huh.ErrUserAborted) {
557				return "", errBootstrapInterrupted
558			}
559			return "", fmt.Errorf("visibility prompt: %w", err)
560		}
561		return selected, nil
562	}
