564	// resolveCommitMessage returns the message to use for the initial
565	// commit. The second return value is false when the user chose to skip
566	// the initial commit entirely; callers must skip `doInitialCommit` and
567	// any subsequent push.
568	func resolveCommitMessage(opts GitHubBootstrapOptions) (string, bool, error) {
569		const defaultMsg = "Initial commit"
570	
571		if opts.SkipInitialCommit {
572			return "", false, nil
573		}
574		if opts.InitialCommitMessage != "" {
575			return opts.InitialCommitMessage, true, nil
576		}
577		if opts.Yes || !interactive.CanPromptInteractively() {
578			return defaultMsg, true, nil
579		}
580	
581		const (
582			choiceDefault   = "default"
583			choiceCustomize = "custom"
584			choiceSkip      = "skip"
585		)
586		choice := choiceDefault
587		form := NewAccessibleForm(
588			huh.NewGroup(
589				huh.NewSelect[string]().
590					Title("Initial commit").
591					Options(
592						huh.NewOption(`Commit with default message "Initial commit"`, choiceDefault),
593						huh.NewOption("Customize message...", choiceCustomize),
594						huh.NewOption("Skip — I'll commit manually later", choiceSkip),
595					).
596					Value(&choice),
597			),
598		)
599		if err := form.Run(); err != nil {
600			if errors.Is(err, huh.ErrUserAborted) {
601				return "", false, errBootstrapInterrupted
602			}
603			return "", false, fmt.Errorf("commit message prompt: %w", err)
604		}
605	
606		switch choice {
607		case choiceSkip:
608			return "", false, nil
609		case choiceCustomize:
610			input := defaultMsg
611			custom := NewAccessibleForm(
612				huh.NewGroup(
613					huh.NewInput().
614						Title("Initial commit message").
615						Value(&input),
616				),
617			)
618			if err := custom.Run(); err != nil {
619				if errors.Is(err, huh.ErrUserAborted) {
620					return "", false, errBootstrapInterrupted
621				}
622				return "", false, fmt.Errorf("commit message prompt: %w", err)
623			}
624			if strings.TrimSpace(input) == "" {
625				return defaultMsg, true, nil
626			}
627			return input, true, nil
628		default:
629			return defaultMsg, true, nil
630		}
631	}
