633	// gitInit runs `git init` in the given directory.
634	func gitInit(ctx context.Context, runner bootstrapRunner, dir string) error {
635		if _, err := runner.RunInDir(ctx, dir, "git", "init"); err != nil {
636			return fmt.Errorf("run git init: %w", err)
637		}
638		return nil
639	}
