641	// doInitialCommit stages all files and creates a commit. Returns whether a
642	// commit was actually created (false if there were no files to stage).
643	func doInitialCommit(ctx context.Context, runner bootstrapRunner, dir, message string) (bool, error) {
644		if _, err := runner.RunInDir(ctx, dir, "git", "add", "-A"); err != nil {
645			return false, wrapExecError("git add", err)
646		}
647		// Check if the staging area has anything at all.
648		out, err := runner.RunInDir(ctx, dir, "git", "status", "--porcelain")
649		if err != nil {
650			return false, wrapExecError("git status", err)
651		}
652		if strings.TrimSpace(out) == "" {
653			return false, nil
654		}
655		// Disable GPG signing for this commit only. Fresh environments often
656		// have commit.gpgsign=true inherited from a global config but no
657		// working signer; passing -c keeps the user's global config intact.
658		if _, err := runner.RunInDir(ctx, dir, "git", "-c", "commit.gpgsign=false", "commit", "-m", message); err != nil {
659			return false, wrapExecError("git commit", err)
660		}
661		return true, nil
662	}
