664	// wrapExecError formats err with stderr from *exec.ExitError when available,
665	// so callers see git's actual complaint instead of an opaque "exit status N".
666	func wrapExecError(prefix string, err error) error {
667		var ee *exec.ExitError
668		if errors.As(err, &ee) {
669			if stderr := strings.TrimSpace(string(ee.Stderr)); stderr != "" {
670				return fmt.Errorf("%s: %w: %s", prefix, err, stderr)
671			}
672		}
673		return fmt.Errorf("%s: %w", prefix, err)
674	}
