676	// ensureGitIdentity guarantees the repo has a user.name/user.email set at
677	// some scope. If neither is configured, we source values from `gh api user`
678	// when available, otherwise prompt (interactive) or fail with a helpful
679	// message (non-interactive). Values are written to the local repo config
680	// only, so the user's global state is never mutated.
681	func ensureGitIdentity(ctx context.Context, w, _ io.Writer, runner bootstrapRunner, dir string) error {
682		// `git config --get` exits non-zero when the key isn't set. Treat any
683		// error as "unset" rather than fatal so we can fall through to sourcing
684		// the identity from elsewhere.
685		nameOut, nameErr := runner.RunInDir(ctx, dir, "git", "config", "--get", "user.name")
686		emailOut, emailErr := runner.RunInDir(ctx, dir, "git", "config", "--get", "user.email")
687		var existingName, existingEmail string
688		if nameErr == nil {
689			existingName = strings.TrimSpace(nameOut)
690		}
691		if emailErr == nil {
692			existingEmail = strings.TrimSpace(emailOut)
693		}
694		if existingName != "" && existingEmail != "" {
695			return nil
696		}
697	
698		// Only try to fill in what's missing. If the user has a name set
699		// globally but no email, we want to keep their name and just source
700		// the email.
701		var ghName, ghEmail string
702		if ghAvailable(ctx, runner) && ghAuthenticated(ctx, runner) {
703			if n, e, err := ghUserIdentity(ctx, runner); err == nil {
704				ghName, ghEmail = n, e
705			}
706		}
707	
708		name, email, err := resolveGitIdentity(w, existingName, existingEmail, ghName, ghEmail)
709		if err != nil {
710			return err
711		}
712	
713		// Write only the fields that were missing. Leaving the already-set
714		// field alone means we never silently replace the user's globally
715		// configured name/email.
716		if existingName == "" {
717			if _, err := runner.RunInDir(ctx, dir, "git", "config", "user.name", name); err != nil {
718				return fmt.Errorf("git config user.name: %w", err)
719			}
720		}
721		if existingEmail == "" {
722			if _, err := runner.RunInDir(ctx, dir, "git", "config", "user.email", email); err != nil {
723				return fmt.Errorf("git config user.email: %w", err)
724			}
725		}
726		return nil
727	}
728	
729	// resolveGitIdentity returns the name/email to use, given any values
730	// already configured at a wider scope and any values from `gh api user`.
731	// Only prompts for fields that are still empty after those fallbacks.
732	func resolveGitIdentity(w io.Writer, existingName, existingEmail, ghName, ghEmail string) (string, string, error) {
733		name := existingName
734		email := existingEmail
735		if name == "" {
736			name = ghName
737		}
738		if email == "" {
739			email = ghEmail
740		}
741	
742		if name != "" && email != "" {
743			// Announce only when we had to fill something in from gh —
744			// silence is fine when the user's existing config covered both.
745			if (existingName == "" && ghName != "") || (existingEmail == "" && ghEmail != "") {
746				fmt.Fprintf(w, "  Using git identity: %s <%s>\n", name, email)
747			}
748			return name, email, nil
749		}
750	
751		if !interactive.CanPromptInteractively() {
752			return "", "", errors.New(`git identity not configured. Set it with:
753	  git config --global user.name "Your Name"
754	  git config --global user.email "you@example.com"`)
755		}
756	
757		// Prompt only for the still-missing fields.
758		var fields []huh.Field
759		if name == "" {
760			fields = append(fields, huh.NewInput().Title("Git user.name").Value(&name))
761		}
762		if email == "" {
763			fields = append(fields, huh.NewInput().Title("Git user.email").Value(&email))
764		}
765		form := NewAccessibleForm(huh.NewGroup(fields...))
766		if err := form.Run(); err != nil {
767			if errors.Is(err, huh.ErrUserAborted) {
768				return "", "", errBootstrapInterrupted
769			}
770			return "", "", fmt.Errorf("git identity prompt: %w", err)
771		}
772		if strings.TrimSpace(name) == "" || strings.TrimSpace(email) == "" {
773			return "", "", errors.New("git user.name and user.email are both required")
774		}
775		return strings.TrimSpace(name), strings.TrimSpace(email), nil
776	}
