778	// ghUserResponse is the subset of `gh api user` fields we care about.
779	type ghUserResponse struct {
780		ID    int64  `json:"id"`
781		Login string `json:"login"`
782		Name  string `json:"name"`
783		Email string `json:"email"`
784	}
785	
786	// ghUserIdentity returns a best-effort (name, email) from `gh api user`.
787	// Missing name falls back to login; missing email falls back to the GitHub
788	// no-reply address, which is always accepted by GitHub.
789	func ghUserIdentity(ctx context.Context, runner bootstrapRunner) (string, string, error) {
790		out, err := runner.Run(ctx, "gh", "api", "user")
791		if err != nil {
792			return "", "", fmt.Errorf("gh api user: %w", err)
793		}
794		var resp ghUserResponse
795		if err := json.Unmarshal([]byte(out), &resp); err != nil {
796			return "", "", fmt.Errorf("parse gh user response: %w", err)
797		}
798		name := resp.Name
799		if name == "" {
800			name = resp.Login
801		}
802		email := resp.Email
803		if email == "" && resp.ID != 0 && resp.Login != "" {
804			email = fmt.Sprintf("%d+%s@users.noreply.github.com", resp.ID, resp.Login)
805		}
806		if name == "" || email == "" {
807			return "", "", errors.New("gh user response missing identity fields")
808		}
809		return name, email, nil
810	}
