851	// ghRepoExists checks whether <owner>/<name> exists on GitHub.
852	func ghRepoExists(ctx context.Context, runner bootstrapRunner, owner, name string) (bool, error) {
853		_, err := runner.Run(ctx, "gh", "repo", "view", owner+"/"+name, "--json", "name")
854		if err == nil {
855			return true, nil
856		}
857		var exitErr *exec.ExitError
858		if errors.As(err, &exitErr) {
859			msg := string(exitErr.Stderr)
860			if strings.Contains(msg, "Could not resolve") || strings.Contains(msg, "not found") || strings.Contains(msg, "Not Found") {
861				return false, nil
862			}
863		}
864		return false, fmt.Errorf("gh repo view: %w", err)
865	}
