867	// ghRepoCreate creates a GitHub repo from the local source directory, adds
868	// origin as its remote, and pushes if there's anything to push.
869	func ghRepoCreate(ctx context.Context, runner bootstrapRunner, dir, fullName, visibility string, hasCommits bool) error {
870		// Create the remote repo and add origin, but don't push yet. We push
871		// separately below with --no-verify so the pre-push hook doesn't run
872		// on this first push: the entire/checkpoints/v1 branch has nothing to
873		// checkpoint (no sessions yet), and if it's pushed alongside the
874		// default branch GitHub can pick it as the default.
875		//
876		// Capture `gh repo create`'s stdout instead of streaming it — its own
877		// "✓ Created repository..." / "✓ Added remote..." lines would
878		// duplicate our own summary in runGitHubBootstrapFinalize.
879		args := []string{
880			"repo", "create", fullName,
881			"--" + visibility,
882			"--source=.",
883			"--remote=origin",
884		}
885		if _, err := runner.RunInDir(ctx, dir, "gh", args...); err != nil {
886			return fmt.Errorf("gh repo create: %w", ghRunnerErr(err))
887		}
888		if hasCommits {
889			// -q silences "Enumerating objects..." etc. --no-verify bypasses
890			// the pre-push hook so entire/checkpoints/v1 isn't pushed
891			// alongside the default branch.
892			if _, err := runner.RunInDir(ctx, dir, "git", "push", "-q", "--no-verify", "-u", "origin", "HEAD"); err != nil {
893				return fmt.Errorf("git push: %w", ghRunnerErr(err))
894			}
895		}
896		return nil
897	}
