899	// ghRunnerErr extracts an exec.ExitError's stderr into the returned
900	// error so the user sees a useful diagnostic when gh/git fail under a
901	// captured-stdout call.
902	func ghRunnerErr(err error) error {
903		var exitErr *exec.ExitError
904		if errors.As(err, &exitErr) && len(exitErr.Stderr) > 0 {
905			return fmt.Errorf("%w: %s", err, strings.TrimSpace(string(exitErr.Stderr)))
906		}
907		return err
908	}
