910	// slugifyRepoName turns a folder name into a GitHub-safe repo name. Invalid
911	// characters are replaced with '-', and runs of '-' are collapsed.
912	func slugifyRepoName(folder string) string {
913		var b strings.Builder
914		b.Grow(len(folder))
915		for _, r := range folder {
916			switch {
917			case (r >= 'a' && r <= 'z') || (r >= 'A' && r <= 'Z') || (r >= '0' && r <= '9'):
918				b.WriteRune(r)
919			case r == '-' || r == '_' || r == '.':
920				b.WriteRune(r)
921			default:
922				b.WriteRune('-')
923			}
924		}
925		slug := b.String()
926		// Collapse repeated dashes.
927		for strings.Contains(slug, "--") {
928			slug = strings.ReplaceAll(slug, "--", "-")
929		}
930		slug = strings.Trim(slug, "-.")
931		if slug == "" {
932			slug = "my-repo"
933		}
934		return slug
935	}
936	
937	// validateRepoName checks whether name is a valid GitHub repo name.
938	func validateRepoName(name string) error {
939		if name == "" {
940			return errors.New("name is required")
941		}
942		if len(name) > 100 {
943			return errors.New("name must be at most 100 characters")
944		}
945		if strings.Contains(name, "/") {
946			return errors.New("name must not contain '/' (pass --repo-owner separately)")
947		}
948		if name == "." || name == ".." {
949			return errors.New("name cannot be '.' or '..'")
950		}
951		if !ghRepoNameRe.MatchString(name) {
952			return errors.New("name may only contain letters, digits, '.', '-', '_'")
953		}
954		return nil
955	}
