68	// fakeRunner is a test seam for bootstrapRunner. Each (name, args[0]) pair
69	// maps to a response.
70	type fakeRunner struct {
71		mu        sync.Mutex
72		responses map[string]fakeResponse
73		calls     []fakeCall
74	}
75	
76	type fakeResponse struct {
77		stdout string
78		err    error
79	}
80	
81	type fakeCall struct {
82		dir  string
83		name string
84		args []string
85	}
86	
87	func newFakeRunner() *fakeRunner {
88		return &fakeRunner{
89			responses: make(map[string]fakeResponse),
90		}
91	}
92	
93	func (f *fakeRunner) key(name string, args []string) string {
94		return name + " " + strings.Join(args, " ")
95	}
96	
97	func (f *fakeRunner) set(name string, args []string, stdout string, err error) {
98		f.mu.Lock()
99		defer f.mu.Unlock()
100		f.responses[f.key(name, args)] = fakeResponse{stdout: stdout, err: err}
101	}
102	
103	func (f *fakeRunner) lookup(name string, args []string) (fakeResponse, bool) {
104		f.mu.Lock()
105		defer f.mu.Unlock()
106		r, ok := f.responses[f.key(name, args)]
107		return r, ok
108	}
109	
110	func (f *fakeRunner) record(dir, name string, args []string) {
111		f.mu.Lock()
112		defer f.mu.Unlock()
113		f.calls = append(f.calls, fakeCall{dir: dir, name: name, args: args})
114	}
115	
116	func (f *fakeRunner) Run(_ context.Context, name string, args ...string) (string, error) {
117		f.record("", name, args)
118		if r, ok := f.lookup(name, args); ok {
119			return r.stdout, r.err
120		}
121		return "", fmt.Errorf("fakeRunner: unexpected call %s %v", name, args)
122	}
123	
124	func (f *fakeRunner) RunInDir(_ context.Context, dir, name string, args ...string) (string, error) {
125		f.record(dir, name, args)
126		if r, ok := f.lookup(name, args); ok {
127			return r.stdout, r.err
128		}
129		return "", fmt.Errorf("fakeRunner: unexpected call in %s: %s %v", dir, name, args)
130	}
