132	// setIdentityConfigured simulates `git config --get user.name/email` returning
133	// non-empty values, so ensureGitIdentity treats identity as already set.
134	func (f *fakeRunner) setIdentityConfigured() {
135		f.set("git", []string{"config", "--get", "user.name"}, "Test User\n", nil)
136		f.set("git", []string{"config", "--get", "user.email"}, "test@example.com\n", nil)
137	}
138	
139	// hasCall returns whether any recorded call matches the predicate.
140	func (f *fakeRunner) hasCall(match func(fakeCall) bool) bool {
141		f.mu.Lock()
142		defer f.mu.Unlock()
143		for _, c := range f.calls {
144			if match(c) {
145				return true
146			}
147		}
148		return false
149	}
