618	// TestRunGitHubBootstrap_InitBeforeFinalize verifies the two-phase split:
619	// init runs git init up front, finalize creates the commit + pushes. A
620	// simulated "agent setup" step writes a file between the phases; that
621	// file must end up in the initial commit (i.e. `git add -A` happens
622	// after setup, not before).
623	func TestRunGitHubBootstrap_InitBeforeFinalize(t *testing.T) {
624		dir := t.TempDir()
625		restoreCwd(t, dir)
626	
627		r := newFakeRunner()
628		r.setIdentityConfigured()
629		r.set("gh", []string{"--version"}, "gh", nil)
630		r.set("gh", []string{"auth", "status"}, "ok", nil)
631		r.set("gh", []string{"api", "user", "--jq", ".login"}, "octocat\n", nil)
632		r.set("gh", []string{"api", "user/orgs", "--jq", ".[].login"}, "", nil)
633		r.set("gh", []string{"repo", "view", "octocat/phased", "--json", "name"}, "", errors.New("not found"))
634		r.set("git", []string{"init"}, "", nil)
635		r.set("git", []string{"add", "-A"}, "", nil)
636		r.set("git", []string{"status", "--porcelain"}, " A .entire/settings.json\n", nil)
637		r.set("git", []string{"-c", "commit.gpgsign=false", "commit", "-m", "First"}, "", nil)
638		r.set("gh", []string{
639			"repo", "create", "octocat/phased",
640			"--private",
641			"--source=.",
642			"--remote=origin",
643		}, "", nil)
644		r.set("git", []string{"push", "-q", "--no-verify", "-u", "origin", "HEAD"}, "", nil)
645	
646		opts := GitHubBootstrapOptions{
647			InitRepo:             true,
648			RepoName:             "phased",
649			RepoVisibility:       "private",
650			InitialCommitMessage: "First",
651		}
652	
653		// Phase 1: init. This must NOT call git add/commit/ gh repo create.
654		state, err := runGitHubBootstrapInitWith(context.Background(), io.Discard, io.Discard, opts, r)
655		if err != nil {
656			t.Fatalf("init failed: %v", err)
657		}
658		if state == nil {
659			t.Fatal("expected non-nil state after init")
660		}
661		forbidden := [][]string{
662			{"add", "-A"},
663			{"status", "--porcelain"},
664			{"-c", "commit.gpgsign=false", "commit", "-m", "First"},
665		}
666		for _, args := range forbidden {
667			if r.hasCall(argsMatch("git", args)) {
668				t.Fatalf("git %v was called during init; should have been deferred to finalize", args)
669			}
670		}
671		if r.hasCall(func(c fakeCall) bool {
672			return c.name == "gh" && len(c.args) >= 2 && c.args[0] == ghSubcmdRepo && c.args[1] == ghActCreate
673		}) {
674			t.Fatal("gh repo create was called during init; should have been deferred to finalize")
675		}
676	
677		// Phase 2: finalize. Now commit + push.
678		if err := runGitHubBootstrapFinalize(context.Background(), io.Discard, state); err != nil {
679			t.Fatalf("finalize failed: %v", err)
680		}
681		if !r.hasCall(argsMatch("git", []string{"-c", "commit.gpgsign=false", "commit", "-m", "First"})) {
682			t.Fatal("expected commit during finalize")
683		}
684		if !r.hasCall(func(c fakeCall) bool {
685			return c.name == "gh" && len(c.args) >= 2 && c.args[0] == ghSubcmdRepo && c.args[1] == ghActCreate
686		}) {
687			t.Fatal("expected gh repo create during finalize")
688		}
689	}
