691	// argsMatch returns a predicate for hasCall that matches when c.name == name
692	// and c.args starts with the given args slice.
693	func argsMatch(name string, args []string) func(fakeCall) bool {
694		return func(c fakeCall) bool {
695			if c.name != name || len(c.args) < len(args) {
696				return false
697			}
698			for i, a := range args {
699				if c.args[i] != a {
700					return false
701				}
702			}
703			return true
704		}
705	}
