847	// TestBootstrap_FreshMachine_RealGit is an integration-style test that runs
848	// real git via execRunner on a temp dir isolated from the user's global git
849	// config. Regression guard for the issue where bootstrap commits failed
850	// without a configured identity or because of commit.gpgsign=true.
851	func TestBootstrap_FreshMachine_RealGit(t *testing.T) {
852		// Isolate from any global git config: point HOME + GIT_CONFIG_* at
853		// empty/missing locations, and force a broken GPG signing config that
854		// would fail any commit if we did not pass -c commit.gpgsign=false.
855		emptyHome := t.TempDir()
856		t.Setenv("HOME", emptyHome)
857		t.Setenv("XDG_CONFIG_HOME", "")
858		// A global config that demands signing with a non-existent program. If
859		// our bootstrap did not override gpgsign for its commit, git would
860		// error out here.
861		globalCfg := filepath.Join(emptyHome, ".gitconfig")
862		globalContent := "[user]\n\tname = Fresh User\n\temail = fresh@example.com\n[commit]\n\tgpgsign = true\n[gpg]\n\tprogram = /does/not/exist\n"
863		if err := writeTempFile(globalCfg, globalContent); err != nil {
864			t.Fatalf("write global gitconfig: %v", err)
865		}
866		t.Setenv("GIT_CONFIG_GLOBAL", globalCfg)
867		// Ensure no system config interferes.
868		t.Setenv("GIT_CONFIG_SYSTEM", "/dev/null")
869	
870		projectDir := t.TempDir()
871		restoreCwd(t, projectDir)
872		// Create a file to commit.
873		if err := writeTempFile(filepath.Join(projectDir, "README.md"), "hello\n"); err != nil {
874			t.Fatalf("write file: %v", err)
875		}
876	
877		opts := GitHubBootstrapOptions{
878			InitRepo:             true,
879			NoGitHub:             true,
880			InitialCommitMessage: "Initial",
881		}
882		err := runGitHubBootstrapWith(context.Background(), io.Discard, io.Discard, opts, execRunner{})
883		if err != nil {
884			t.Fatalf("bootstrap failed: %v", err)
885		}
886	
887		// Verify a commit actually landed on HEAD.
888		out, err := execRunner{}.RunInDir(context.Background(), projectDir, "git", "log", "--oneline")
889		if err != nil {
890			t.Fatalf("git log failed: %v", err)
891		}
892		if !strings.Contains(out, "Initial") {
893			t.Fatalf("expected 'Initial' commit in log, got: %q", out)
894		}
895	}
